@prefix dc: <http://purl.org/dc/elements/1.1/> .
@prefix dcterms: <http://purl.org/dc/terms/> .
@prefix foaf: <http://xmlns.com/foaf/0.1/> .
@prefix ns: <http://www.w3.org/2003/06/sw-vocab-status/ns#> .
@prefix odrl: <http://www.w3.org/ns/odrl/2/> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix schema: <https://schema.org/> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix ns2: <https://example.org/ns2/> .
@prefix ns3: <http://www.cidoc-crm.org/cidoc-crm/> . # Assuming this namespace for CRM entities

<http://example.org/dahlem_museum_foyer> a ns3:E53_Place ;
    schema:description "The upper foyer of the Dahlem Museum where a concert took place." .

<http://example.org/dahlem_museum> a ns2:CACAO_0000020 ;
    schema:description "Dahlem Museum" .

<http://example.org/dahlem_museum_concert> a ns3:E5_Event ;
    ns3:P7_took_place_at <http://example.org/dahlem_museum_foyer> ;
    schema:description "A concert featuring Egyptian folk music at the Dahlem Museum in June 1977." .

<http://example.org/arab_students> a foaf:Group ;
    rdfs:label "Arab Students" ;
    schema:description "Happily gesticulating Arab students attending the concert." ;
    ns3:P11i_participated_in <http://example.org/dahlem_museum_concert> .

<http://example.org/department_of_ethnomusicology> a foaf:Organization ;
    rdfs:label "Department of Ethnomusicology" ;
    schema:description "The Department of Ethnomusicology that invited the music groups." ;
    ns3:P14_carried_out_by <http://example.org/dahlem_museum_concert> .

<http://example.org/khufu-anch> a schema:Person ;
    rdfs:label "Khufu-anch" ;
    schema:description "Court music director of the pharaohs, flute virtuoso, and singer, considered an ancestor of the musicians." ;
    schema:roleName "Court music director", "Flute virtuoso", "Singer" .

<http://example.org/egyptian_folk_music_history> a schema:CreativeWork ;
    schema:description "Folk music in Egypt has been practiced by itinerant professional musicians for 5,000 years, passed on within families, and resists European influence and commercialization." .

<http://example.org/folk_music_traditions> a ns2:CACAO_0000010 ;
    rdfs:label "Folk Music Traditions" ;
    schema:description "Traditional folk music practices include performances at weddings, saint celebrations, circumcisions, greeting pilgrims, and accompanying village dances." .

<http://example.org/mizmar_baladi_ensemble> a foaf:Group ;
    rdfs:label "Mizmar-baladi ensemble" ;
    schema:description "A music group from the south of Egypt, performing 'mizmar-baladi' music." ;
    ns3:P11i_participated_in <http://example.org/dahlem_museum_concert> .

<http://example.org/mizmar_instrument> a ns2:CACAO_0000025 ;
    rdfs:label "Mizmar (Oboe)" ;
    schema:description "Three oboes with narrower and wider bores, circling around the melody in a small tonal range and heterophonic style." ;
    ns3:P46i_forms_part_of <http://example.org/mizmar_baladi_ensemble> .

<http://example.org/large_drum_instrument> a ns2:CACAO_0000025 ;
    rdfs:label "Large Drum" ;
    schema:description "A large drum providing meter for the mizmar-baladi ensemble." ;
    ns3:P46i_forms_part_of <http://example.org/mizmar_baladi_ensemble> .

<http://example.org/small_kettledrum_instrument> a ns2:CACAO_0000025 ;
    rdfs:label "Small Kettledrum" ;
    schema:description "A small kettledrum, beaten in a virtuosic way with small sticks, providing meter for the mizmar-baladi ensemble." ;
    ns3:P46i_forms_part_of <http://example.org/mizmar_baladi_ensemble> .

<http://example.org/stick_dancers> a foaf:Group ;
    rdfs:label "Stick Dancers" ;
    schema:description "Two stick dancers performing pantomime dances inspired by folk subjects alongside the drum players." ;
    ns3:P11i_participated_in <http://example.org/dahlem_museum_concert> ;
    ns3:P107i_is_current_or_former_member_of <http://example.org/mizmar_baladi_ensemble> .

<http://example.org/european_musical_virtuosity> a skos:Concept ;
    rdfs:label "European concept of meticulous musical virtuosity" .

<http://example.org/collective_experience_art> a skos:Concept ;
    rdfs:label "Art arising from collective experience and sensation" .

<http://example.org/second_music_group> a foaf:Group ;
    rdfs:label "Second Music Group (Upper Egypt)" ;
    schema:description "A music group representative of Upper Egyptian music, which retreated due to Islamization and Europeanization in the north." ;
    ns3:P11i_participated_in <http://example.org/dahlem_museum_concert> .

<http://example.org/double_clarinet_instrument> a ns2:CACAO_0000025 ;
    rdfs:label "Double Clarinet" ;
    schema:description "Characterized by drone-like sustained notes and a burring and dinning sound." ;
    ns3:P46i_forms_part_of <http://example.org/second_music_group> .

<http://example.org/rebabah_instrument> a ns2:CACAO_0000025 ;
    rdfs:label "Rebabah" ;
    schema:description "A spike fiddle with two strings, used for improvisation and accompanying songs." ;
    ns3:P46i_forms_part_of <http://example.org/second_music_group> .

<http://example.org/end_blown_flute_instrument> a ns2:CACAO_0000025 ;
    rdfs:label "End-Blown Flute" ;
    schema:description "An end-blown flute used for improvisation." ;
    ns3:P46i_forms_part_of <http://example.org/second_music_group> .

<http://example.org/rebabah_player> a schema:Person ;
    rdfs:label "Rebabah Player" ;
    schema:description "A musician who plays the rebabah and sings popular traditional song-narratives." ;
    ns3:P11i_participated_in <http://example.org/dahlem_museum_concert> ;
    ns3:P107i_is_current_or_former_member_of <http://example.org/second_music_group> .

<http://example.org/song_narratives> a schema:CreativeWork ;
    rdfs:label "Traditional Song-Narratives" ;
    schema:description "Popular traditional song-narratives treating subjects like the countryside, love, and nature." ;
    ns3:P129i_is_subject_of <http://example.org/rebabah_player> . # The player is the subject of performing them

<http://example.org/countryside_theme> a skos:Concept ;
    rdfs:label "Countryside (theme)" .

<http://example.org/love_theme> a skos:Concept ;
    rdfs:label "Love (theme)" .

<http://example.org/nature_theme> a skos:Concept ;
    rdfs:label "Nature (theme)" .

<http://example.org/duff_instrument> a ns2:CACAO_0000025 ;
    rdfs:label "Duff" ;
    schema:description "A percussion instrument linked to African off-beat rhythms." ;
    ns3:P46i_forms_part_of <http://example.org/second_music_group> .

<http://example.org/tabla_instrument> a ns2:CACAO_0000025 ;
    rdfs:label "Tabla" ;
    schema:description "A percussion instrument linked to African off-beat rhythms." ;
    ns3:P46i_forms_part_of <http://example.org/second_music_group> .

<http://example.org/airplane_imitation> a schema:CreativeWork ;
    rdfs:label "Airplane Imitation (Music Piece)" ;
    schema:description "A newer musical piece imitating an 'airplane' sound, with a sound resembling a bee's flight." ;
    ns3:P129i_is_subject_of <http://example.org/second_music_group> .

<http://example.org/der_tagesspiegel> a schema:CreativeWork, foaf:Document ;
    rdfs:label "Der Tagesspiegel" ;
    dcterms:date "1977-06-06"^^xsd:date ;
    schema:description "Newspaper article from 'Der Tagesspiegel', Berlin." .

<http://example.org/concert_excerpt_image> a ns2:CACAO_0000086 ;
    schema:description "Image of stick dancers and musicians of the mizmar-baladi ensemble during the concert (pp. 256-7)." ;
    ns3:P129_is_about <http://example.org/mizmar_baladi_ensemble> ;
    ns3:P129_is_about <http://example.org/stick_dancers> .

<http://example.org/oldest_musician> a schema:Person ;
    rdfs:label "Oldest Musician" ;
    schema:age "60"^^xsd:integer ;
    ns3:P11i_participated_in <http://example.org/dahlem_museum_concert> .

<http://example.org/youngest_musician> a schema:Person ;
    rdfs:label "Youngest Musician" ;
    schema:age "15"^^xsd:integer ;
    ns3:P11i_participated_in <http://example.org/dahlem_museum_concert> .
